ow['status'])) ?></span></td><td><div class="vehicle-actions"><a class="vehicle-action" href="index.php?page=admin&amp;section=vehicles-view&amp;id=<?= (int) $row['id'] ?>" title="View vehicle">◉</a><a class="vehicle-action vehicle-edit" href="index.php?page=admin&amp;section=vehicles-edit&amp;id=<?= (int) $row['id'] ?>" title="Edit vehicle">✎</a><form method="post" action="index.php?page=admin&amp;section=vehicles-remove&amp;id=<?= (int) $row['id'] ?>" data-vehicle-remove-form data-vehicle-number="<?= e($row['vehicle_number']) ?>"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><button class="vehicle-action vehicle-remove" type="submit" title="Remove vehicle">×</button></form></div></td></tr><?php endforeach; ?><?php endif; ?></tbody></table></div><div class="customer-table-footer"><span>Showing <?= $start ?> to <?= $end ?> of <?= $total ?> vehicles</span><?php if ($pages > 1): ?><nav aria-label="Vehicle pagination"><ul class="pagination pagination-sm mb-0"><?php for ($number = 1; $number <= $pages; $number++): ?><li class="page-item <?= $number === $filters['page'] ? 'active' : '' ?>"><a class="page-link" href="index.php?page=admin&amp;section=vehicles&amp;p=<?= $number ?>&amp;per_page=<?= $filters['per_page'] ?>"><?= $number ?></a></li><?php endfor; ?></ul></nav><?php endif; ?></div></div>

